package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"net/http"
	"strconv"
	"sync"
	"time"
)

const (
	sharedSecret = "device-fleet-key-2024"
	nonceWindow  = 30 // seconds
)

type AuthState struct {
	mu            sync.Mutex
	pendingNonces map[string]int64
	usedNonces    map[string]bool
	firmwareVer   string
	updatePending bool
}

var state = &AuthState{
	pendingNonces: make(map[string]int64),
	usedNonces:    make(map[string]bool),
	firmwareVer:   "1.0.0",
}

func computeMAC(message, key string) string {
	mac := hmac.New(sha256.New, []byte(key))
	mac.Write([]byte(message))
	return hex.EncodeToString(mac.Sum(nil))
}

func verifyMAC(message, messageMAC, key string) bool {
	expectedMAC := computeMAC(message, key)
	return hmac.Equal([]byte(expectedMAC), []byte(messageMAC))
}

// Phase 1: Service announces intent to authenticate
func handleAuthInit(w http.ResponseWriter, r *http.Request) {
	nonce := r.Header.Get("X-Auth-Nonce")
	timestampStr := r.Header.Get("X-Auth-Timestamp")
	serviceID := r.Header.Get("X-Service-ID")

	if nonce == "" || timestampStr == "" || serviceID == "" {
		http.Error(w, "missing headers", http.StatusBadRequest)
		return
	}

	timestamp, err := strconv.ParseInt(timestampStr, 10, 64)
	if err != nil {
		http.Error(w, "invalid timestamp", http.StatusBadRequest)
		return
	}

	now := time.Now().Unix()
	if abs(now-timestamp) > int64(nonceWindow) {
		http.Error(w, "timestamp outside window", http.StatusUnauthorized)
		return
	}

	state.mu.Lock()
	state.pendingNonces[nonce] = timestamp
	state.mu.Unlock()

	challenge := computeMAC(fmt.Sprintf("%s:%s:%d", serviceID, nonce, timestamp), sharedSecret)
	w.Header().Set("X-Challenge", challenge)
	w.WriteHeader(http.StatusOK)
}

// Phase 2: Service completes authentication and issues command
func handleAuthComplete(w http.ResponseWriter, r *http.Request) {
	nonce := r.Header.Get("X-Auth-Nonce")
	responseMAC := r.Header.Get("X-Auth-Response")
	serviceID := r.Header.Get("X-Service-ID")
	command := r.Header.Get("X-Command")

	if nonce == "" || responseMAC == "" || serviceID == "" || command == "" {
		http.Error(w, "missing headers", http.StatusBadRequest)
		return
	}

	state.mu.Lock()
	timestamp, exists := state.pendingNonces[nonce]
	if !exists {
		state.mu.Unlock()
		http.Error(w, "unknown nonce", http.StatusUnauthorized)
		return
	}
	// Remove from pending - nonce is being consumed
	delete(state.pendingNonces, nonce)
	state.mu.Unlock()

	// Verify the response MAC
	expectedMsg := fmt.Sprintf("%s:%s:%d:%s", serviceID, nonce, timestamp, command)
	if !verifyMAC(expectedMsg, responseMAC, sharedSecret) {
		http.Error(w, "authentication failed", http.StatusUnauthorized)
		return
	}

	// Check replay AFTER verification but BEFORE execution
	state.mu.Lock()
	if state.usedNonces[nonce] {
		state.mu.Unlock()
		http.Error(w, "nonce already used", http.StatusConflict)
		return
	}
	state.usedNonces[nonce] = true
	state.mu.Unlock()

	executeCommand(command, w)
}

func executeCommand(command string, w http.ResponseWriter) {
	switch command {
	case "get_status":
		fmt.Fprintf(w, "firmware: %s, update_pending: %v", state.firmwareVer, state.updatePending)
	case "apply_update":
		state.mu.Lock()
		state.updatePending = true
		state.mu.Unlock()
		fmt.Fprintf(w, "update scheduled")
	case "factory_reset":
		state.mu.Lock()
		state.firmwareVer = "1.0.0"
		state.updatePending = false
		state.mu.Unlock()
		fmt.Fprintf(w, "factory reset initiated")
	default:
		http.Error(w, "unknown command", http.StatusBadRequest)
	}
}

func abs(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}

func main() {
	http.HandleFunc("/auth/init", handleAuthInit)
	http.HandleFunc("/auth/complete", handleAuthComplete)
	fmt.Println("IoT device firmware auth service starting on :8443")
	http.ListenAndServe(":8443", nil)
}
